import { Injectable } from '@nestjs/common';
import type { DevicePlatform, Prisma } from '../../../generated/prisma/client.js';

export interface DeviceInput {
  readonly installationId: string;
  readonly platform: DevicePlatform;
  readonly model?: string | undefined;
  readonly appVersion?: string | undefined;
}

export interface DeviceRecord {
  readonly id: string;
  readonly trustedAt: Date | null;
}

/**
 * Devices are app installations (a random installation id generated by the app). A device
 * becomes trusted once the user proves phone possession on it with an SMS code; untrusted
 * devices need that code at login (new-device step-up).
 */
@Injectable()
export class DeviceService {
  async find(
    db: Prisma.TransactionClient,
    userId: string,
    installationId: string,
  ): Promise<DeviceRecord | null> {
    return db.device.findUnique({
      where: { userId_installationId: { userId, installationId } },
      select: { id: true, trustedAt: true },
    });
  }

  async upsert(
    db: Prisma.TransactionClient,
    userId: string,
    device: DeviceInput,
    options: { trust: boolean },
  ): Promise<DeviceRecord> {
    const now = new Date();
    const details = {
      platform: device.platform,
      model: device.model ?? null,
      appVersion: device.appVersion ?? null,
    };
    return db.device.upsert({
      where: { userId_installationId: { userId, installationId: device.installationId } },
      create: {
        userId,
        installationId: device.installationId,
        ...details,
        lastSeenAt: now,
        trustedAt: options.trust ? now : null,
      },
      update: { ...details, lastSeenAt: now, ...(options.trust ? { trustedAt: now } : {}) },
      select: { id: true, trustedAt: true },
    });
  }

  async untrust(db: Prisma.TransactionClient, deviceId: string): Promise<void> {
    await db.device.update({ where: { id: deviceId }, data: { trustedAt: null } });
  }

  async untrustAll(
    db: Prisma.TransactionClient,
    userId: string,
    exceptDeviceId?: string,
  ): Promise<void> {
    await db.device.updateMany({
      where: { userId, ...(exceptDeviceId === undefined ? {} : { id: { not: exceptDeviceId } }) },
      data: { trustedAt: null },
    });
  }
}
